async function currentUser(req){const t=token(req);if(!t)return null;const th=crypto.createHash("sha256").update(t).digest("hex"),q=await pool.query("SELECT u.id,u.company_id,u.email,u.display_name,u.role,u.avatar_data,u.must_change_password FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token_hash=$1 AND s.expires_at>now() AND u.status='active'",[th]);return q.rows[0]||null}
async function auth(req,res){const u=await currentUser(req);if(!u)json(res,401,{error:"Nicht angemeldet"});return u}
async function hasRawFeature(companyId,code){const q=await pool.query("SELECT 1 FROM company_features WHERE company_id=$1 AND feature_code=$2 AND status='active' AND ((ends_at IS NULL OR ends_at>now()) OR (grace_until IS NOT NULL AND grace_until>now()))",[companyId,code]);return !!q.rowCount}
async function hasFeature(companyId,code){if(code==="restaurant")return await hasRawFeature(companyId,"pos_base")&&await hasRawFeature(companyId,"restaurant");if(code==="table_qr")return await hasRawFeature(companyId,"pos_base")&&await hasRawFeature(companyId,"restaurant")&&await hasRawFeature(companyId,"table_qr");return hasRawFeature(companyId,code)}
async function requireFeature(x,res,code){if(await hasFeature(x.company_id,code))return true;json(res,402,{error:"Diese Funktion ist in Ihrer Lizenz nicht enthalten.",feature:code,upgradeRequired:true});return false}
