if(p==="/api/v1/profile/avatar"&&req.method==="PUT"){const x=await auth(req,res);if(!x)return;const b=await body(req),avatar=String(b.avatar||"");if(!/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(avatar)||avatar.length>200000)return json(res,400,{error:"Bitte ein PNG-, JPEG- oder WebP-Bild bis 150 KB auswählen."});await pool.query("UPDATE users SET avatar_data=$1 WHERE id=$2",[avatar,x.id]);return json(res,200,{avatar})}
