if(p==="/api/v1/auth/login"&&req.method==="POST"){const b=await body(req),q=await pool.query("SELECT id,email,display_name FROM users WHERE email=$1 AND password_hash=$2 AND status='active'",[String(b.email||"").trim().toLowerCase(),hash(String(b.password||""))]);if(!q.rows[0])return json(res,401,{error:"Anmeldedaten stimmen nicht"});const x=q.rows[0],t=await session(x.id);return json(res,200,{token:t,user:{id:x.id,name:x.display_name,email:x.email}})}
