if(p==="/api/v1/devices/heartbeat"&&req.method==="POST"){const x=await auth(req,res);if(!x)return;const b=await body(req),q=await pool.query("UPDATE devices SET last_seen_at=now(),app_version=$3 WHERE device_key=$1 AND company_id=$2 RETURNING id,status",[String(b.deviceKey||""),x.company_id,String(b.appVersion||"").slice(0,30)]);if(!q.rows[0])return json(res,404,{error:"Gerät nicht registriert"});const cmds=await pool.query("SELECT id,command,created_at FROM device_commands WHERE device_id=$1 AND status='pending' ORDER BY created_at LIMIT 10",[q.rows[0].id]);return json(res,200,{status:q.rows[0].status,commands:cmds.rows})}
